// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }
    function testRegression_property() public {
        MockERC721 nft = new MockERC721();
        uint256 tokenId = 1;
        nft.mint(address(this), tokenId);

        nft.approve(address(c), tokenId);

        bool success;
        try nft.safeTransferFrom(address(this), address(c), tokenId) {
            success = true;
        } catch {
            success = false;
        }

        assertTrue(success, "safeTransferFrom should succeed on reference, but might fail on mutant");
    }
}

contract MockERC721 {
    string public name = "MockNFT";
    string public symbol = "MNFT";

    mapping(uint256 => address) private _owners;
    mapping(address => uint256) private _balances;
    mapping(uint256 => address) private _tokenApprovals;
    mapping(address => mapping(address => bool)) private _operatorApprovals;

    function mint(address to, uint256 tokenId) external {
        _owners[tokenId] = to;
        _balances[to]++;
    }

    function approve(address spender, uint256 tokenId) external {
        _tokenApprovals[tokenId] = spender;
    }

    function ownerOf(uint256 tokenId) public view returns (address) {
        return _owners[tokenId];
    }

    function balanceOf(address owner) public view returns (uint256) {
        return _balances[owner];
    }

    function getApproved(uint256 tokenId) public view returns (address) {
        return _tokenApprovals[tokenId];
    }

    function isApprovedForAll(address owner, address operator) public view returns (bool) {
        return _operatorApprovals[owner][operator];
    }

    function safeTransferFrom(address from, address to, uint256 tokenId) external {
        require(from == _owners[tokenId], "WRONG_FROM");
        require(to != address(0), "INVALID_RECIPIENT");
        require(
            msg.sender == from || _operatorApprovals[from][msg.sender] || msg.sender == _tokenApprovals[tokenId],
            "NOT_AUTHORIZED"
        );

        _balances[from]--;
        _balances[to]++;
        _owners[tokenId] = to;
        delete _tokenApprovals[tokenId];

        if (to.code.length > 0) {
            bytes4 ret = ERC721TokenReceiver(to).onERC721Received(msg.sender, from, tokenId, "");
            require(ret == 0x150b7a02, "UNSAFE_RECIPIENT");
        }
    }
}

abstract contract ERC721TokenReceiver {
    function onERC721Received(
        address,
        address,
        uint256,
        bytes calldata
    ) external virtual returns (bytes4) {
        return 0x150b7a02;
    }
}
